BEGIN;
SET LOCAL session_replication_role = replica;
CREATE SCHEMA IF NOT EXISTS corpus_verification_audit;
CREATE TABLE IF NOT EXISTS corpus_verification_audit.original_claims AS SELECT * FROM public.claims;
CREATE TABLE IF NOT EXISTS corpus_verification_audit.original_claim_epistemics AS SELECT * FROM public.claim_epistemics;
CREATE TABLE IF NOT EXISTS corpus_verification_audit.original_claim_sources AS SELECT * FROM public.claim_sources;
CREATE TABLE IF NOT EXISTS corpus_verification_audit.original_claim_chunks AS SELECT * FROM public.claim_chunks;
CREATE TABLE IF NOT EXISTS corpus_verification_audit.decisions (claim_id uuid PRIMARY KEY, decision text NOT NULL, evidence_record jsonb NOT NULL, applied_at timestamptz NOT NULL DEFAULT now());
DO $$ BEGIN IF (SELECT count(*) FROM corpus_verification_audit.original_claims) <> 1585 THEN RAISE EXCEPTION 'baseline mismatch'; END IF; END $$;
ALTER TABLE public.claims DROP CONSTRAINT IF EXISTS claims_approval_origin_check;
ALTER TABLE public.claims ADD CONSTRAINT claims_approval_origin_check CHECK (approval_origin IN ('human_manual','mentor_review','system_test_bulk','imported_existing','ai_candidate','automated_evidence_verification','corpus_evidence_review'));
UPDATE public.claims SET review_status='needs_review', approved_at=NULL, approved_by_label=NULL WHERE review_status <> 'rejected';
INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('1c773840-34a3-435e-8e8d-f51227baa7a5'::uuid,'REVISE AND APPROVE','{"claim_id":"1c773840-34a3-435e-8e8d-f51227baa7a5","personality_id":"96abdf31-9bb6-4fa9-8e02-1508cdcba4c9","personality":"A. P. J. Abdul Kalam","original_claim_text":"The first experimental SLV-3 flight in August 1979 was only partially successful; the programme reached orbit on its next attempt in July 1980.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"],"original_passage_ids":["7ad920fe-d6e8-4411-a9fc-1d0ffafb5c9e"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The first experimental SLV-3 flight in August 1979 was only partially successful; the next launch, on July 18, 1980, placed Rohini RS-1 in orbit.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"url":"https://www.isro.gov.in/SLV.html","locator":"SLV, introductory paragraphs, lines 4–6","source_id":"b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"}],"verification_rationale":"ISRO''s mission history directly gives both flight outcomes and the July 18 date. Institutional original record is adequate for this narrowly scoped launch chronology. The original wording was precise enough, but the proposed wording names the satellite and date for clarity.","original_source_inspected":false,"material_limitation":null,"removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='The first experimental SLV-3 flight in August 1979 was only partially successful; the next launch, on July 18, 1980, placed Rohini RS-1 in orbit.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='1c773840-34a3-435e-8e8d-f51227baa7a5'::uuid;
UPDATE public.claim_epistemics SET epistemic_type='HISTORICAL_FACT',contract_status='SUPPORTED',contract_satisfied=true,contract_basis='Source-specific corpus review; see corpus_verification_audit.decisions',reviewer_kind='ai_assisted',review_note='Evidence assessment in isolated review copy',reviewed_at=now() WHERE claim_id='1c773840-34a3-435e-8e8d-f51227baa7a5'::uuid;
INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('0056e637-ab83-4d5e-906a-a4fd1a6add5a'::uuid,'REVISE AND APPROVE','{"claim_id":"0056e637-ab83-4d5e-906a-a4fd1a6add5a","personality_id":"96abdf31-9bb6-4fa9-8e02-1508cdcba4c9","personality":"A. P. J. Abdul Kalam","original_claim_text":"The July 1980 SLV-3 launch placed Rohini RS-1 in orbit and established an indigenous Indian satellite-launch capability.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"],"original_passage_ids":["242879fb-5694-4ea4-b156-57d9e182a963"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"On July 18, 1980, India''s SLV-3 placed the Rohini RS-1 satellite in orbit.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"url":"https://www.isro.gov.in/SLV.html","locator":"SLV, launch account, line 4","source_id":"b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"}],"verification_rationale":"ISRO directly confirms the launch date and orbital placement. The broad claim that this ''established an indigenous Indian satellite-launch capability'' is interpretive and was removed.","original_source_inspected":false,"material_limitation":null,"removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='On July 18, 1980, India''s SLV-3 placed the Rohini RS-1 satellite in orbit.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='0056e637-ab83-4d5e-906a-a4fd1a6add5a'::uuid;
UPDATE public.claim_epistemics SET epistemic_type='HISTORICAL_FACT',contract_status='SUPPORTED',contract_satisfied=true,contract_basis='Source-specific corpus review; see corpus_verification_audit.decisions',reviewer_kind='ai_assisted',review_note='Evidence assessment in isolated review copy',reviewed_at=now() WHERE claim_id='0056e637-ab83-4d5e-906a-a4fd1a6add5a'::uuid;
INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('0ad9f692-4372-4895-936d-6383d12a7a96'::uuid,'REVISE AND APPROVE','{"claim_id":"0ad9f692-4372-4895-936d-6383d12a7a96","personality_id":"96abdf31-9bb6-4fa9-8e02-1508cdcba4c9","personality":"A. P. J. Abdul Kalam","original_claim_text":"ISRO presents SLV-3 as a foundation for later ASLV, PSLV, and GSLV projects, rather than as Kalam''s achievement alone.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"],"original_passage_ids":["9e0db2ad-6b2a-4ad4-9cde-fbcecbf949b5"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"ISRO says the successful SLV-3 project paved the way for the later ASLV, PSLV, and GSLV launch-vehicle projects.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"url":"https://www.isro.gov.in/SLV.html","locator":"SLV, final paragraph, line 7","source_id":"b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"}],"verification_rationale":"The agency explicitly links the SLV-3 project to the three later programmes. The comparative attribution to Kalam alone is not established by this page, so it was omitted.","original_source_inspected":false,"material_limitation":null,"removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='ISRO says the successful SLV-3 project paved the way for the later ASLV, PSLV, and GSLV launch-vehicle projects.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='0ad9f692-4372-4895-936d-6383d12a7a96'::uuid;
UPDATE public.claim_epistemics SET epistemic_type='TEXTUAL_ASSERTION',contract_status='SUPPORTED',contract_satisfied=true,contract_basis='Source-specific corpus review; see corpus_verification_audit.decisions',reviewer_kind='ai_assisted',review_note='Evidence assessment in isolated review copy',reviewed_at=now() WHERE claim_id='0ad9f692-4372-4895-936d-6383d12a7a96'::uuid;
INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('bbaeed4c-7325-42ef-b531-88ec1c970ac6'::uuid,'REVISE AND APPROVE','{"claim_id":"bbaeed4c-7325-42ef-b531-88ec1c970ac6","personality_id":"96abdf31-9bb6-4fa9-8e02-1508cdcba4c9","personality":"A. P. J. Abdul Kalam","original_claim_text":"The SLV-3 programme developed a four-stage solid-propellant launch vehicle able to place small payloads in low Earth orbit.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"],"original_passage_ids":["556015d9-a56b-4758-b25c-e813635a0168"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The SLV-3 was a four-stage, all-solid launch vehicle designed to place roughly 40 kg payloads in low Earth orbit.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"url":"https://www.isro.gov.in/SLV.html","locator":"SLV, opening paragraph, line 2","source_id":"b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"}],"verification_rationale":"ISRO''s vehicle description directly supports the configuration and payload capacity. Wording specifies the documented approximate capacity.","original_source_inspected":false,"material_limitation":null,"removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='The SLV-3 was a four-stage, all-solid launch vehicle designed to place roughly 40 kg payloads in low Earth orbit.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='bbaeed4c-7325-42ef-b531-88ec1c970ac6'::uuid;
UPDATE public.claim_epistemics SET epistemic_type='HISTORICAL_FACT',contract_status='SUPPORTED',contract_satisfied=true,contract_basis='Source-specific corpus review; see corpus_verification_audit.decisions',reviewer_kind='ai_assisted',review_note='Evidence assessment in isolated review copy',reviewed_at=now() WHERE claim_id='bbaeed4c-7325-42ef-b531-88ec1c970ac6'::uuid;
INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('6eedc4ab-6cff-40c8-bad8-c616cd941467'::uuid,'REVISE AND APPROVE','{"claim_id":"6eedc4ab-6cff-40c8-bad8-c616cd941467","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"Chronology is genuinely contested: scholars have proposed 788–820, roughly 700–750, and other ranges; the corpus therefore uses “eighth century” with qualifications rather than a falsely exact lifespan.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["da61510f-9779-46c0-b5af-2f4aaefb9b94"],"original_passage_ids":["b2eef562-2758-4a09-8b04-32aab6927214"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Scholarly datings of Shankara differ: proposed ranges include 788–820 CE, 700–750 CE, and the late seventh to early eighth centuries.","epistemic_type":"CONTESTED","evidence_references":[{"source_id":"da61510f-9779-46c0-b5af-2f4aaefb9b94","url":"https://plato.stanford.edu/entries/shankara/","locator":"Life and Works, line 44","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"SEP enumerates the three dating proposals. The internal corpus-policy sentence was removed; none of these ranges is treated as settled.","original_source_inspected":true,"material_limitation":null,"removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Scholarly datings of Shankara differ: proposed ranges include 788–820 CE, 700–750 CE, and the late seventh to early eighth centuries.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='6eedc4ab-6cff-40c8-bad8-c616cd941467'::uuid;
UPDATE public.claim_epistemics SET epistemic_type='CONTESTED',contract_status='SUPPORTED',contract_satisfied=true,contract_basis='Source-specific corpus review; see corpus_verification_audit.decisions',reviewer_kind='ai_assisted',review_note='Evidence assessment in isolated review copy',reviewed_at=now() WHERE claim_id='6eedc4ab-6cff-40c8-bad8-c616cd941467'::uuid;
INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('110d5f9b-661f-496b-b5ef-0ee082f0502b'::uuid,'APPROVE','{"claim_id":"110d5f9b-661f-496b-b5ef-0ee082f0502b","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"Post-Shankara Advaita developed major Bhamati and Vivarana sub-schools, especially through differing accounts of avidya; later Advaita should not be automatically projected back onto Shankara.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["a2a0752d-ffce-4a6f-b5a9-77186913ac3e"],"original_passage_ids":["a3a0c741-f140-4f4d-9603-b281e33cb5e0"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Post-Shankara Advaita developed major Bhamati and Vivarana sub-schools, especially through differing accounts of avidya; later Advaita should not be automatically projected back onto Shankara.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"a2a0752d-ffce-4a6f-b5a9-77186913ac3e","url":"https://iep.utm.edu/advaita-vedanta/","locator":"History, lines 23–24; Brahman/Jiva section, lines 40–43","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"IEP identifies the two later schools and their differing accounts of avidya; the warning against projecting later positions backward follows the chronology.","original_source_inspected":true,"material_limitation":"Interpretive claims are attributed to the scholarly entry; primary commentary or an independent specialist study may refine details.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Post-Shankara Advaita developed major Bhamati and Vivarana sub-schools, especially through differing accounts of avidya; later Advaita should not be automatically projected back onto Shankara.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='110d5f9b-661f-496b-b5ef-0ee082f0502b'::uuid;
