INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('6146df78-6954-40d4-992d-034606ddcd8d'::uuid,'APPROVE','{"claim_id":"6146df78-6954-40d4-992d-034606ddcd8d","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"Mandana Misra represents an important near-contemporary Advaita-related interlocutor: he gave greater weight than Shankara to combining knowledge and action on the path to liberation.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["a2a0752d-ffce-4a6f-b5a9-77186913ac3e"],"original_passage_ids":["cff7de8f-b2e6-42ac-918b-a66f8c42c0c8"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Mandana Misra represents an important near-contemporary Advaita-related interlocutor: he gave greater weight than Shankara to combining knowledge and action on the path to liberation.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"a2a0752d-ffce-4a6f-b5a9-77186913ac3e","url":"https://iep.utm.edu/advaita-vedanta/","locator":"History, lines 22–23","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"IEP directly contrasts Mandana Misra''s greater accommodation of knowledge and works with Shankara''s knowledge-only position.","original_source_inspected":true,"material_limitation":"Interpretive claims are attributed to the scholarly entry; primary commentary or an independent specialist study may refine details.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Mandana Misra represents an important near-contemporary Advaita-related interlocutor: he gave greater weight than Shankara to combining knowledge and action on the path to liberation.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='6146df78-6954-40d4-992d-034606ddcd8d'::uuid;
