INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('8f24c364-a473-4359-a500-77dbf397cd9e'::uuid,'APPROVE','{"claim_id":"8f24c364-a473-4359-a500-77dbf397cd9e","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"Textual evidence discussed by historians suggests pre-Shankara Brahma Sutra commentaries took Bhedabheda-like positions, clarifying that Shankara’s nondual reading entered a field of competing Vedanta interpretations.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["71da4400-6fe9-49cd-808c-8cec554ee3a8"],"original_passage_ids":["c9c9bd4f-814c-4a5e-89f2-6333e3fd45d0"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Textual evidence discussed by historians suggests pre-Shankara Brahma Sutra commentaries took Bhedabheda-like positions, clarifying that Shankara’s nondual reading entered a field of competing Vedanta interpretations.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"71da4400-6fe9-49cd-808c-8cec554ee3a8","url":"https://iep.utm.edu/hindu-ph/","locator":"Vedanta, Bhedabheda, lines 234–240","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"IEP explicitly describes textual evidence for Bhedabheda-like pre-Shankara commentaries, noting that most are lost; the claim preserves the evidential qualifier.","original_source_inspected":true,"material_limitation":"Interpretive claims are attributed to the scholarly entry; primary commentary or an independent specialist study may refine details.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Textual evidence discussed by historians suggests pre-Shankara Brahma Sutra commentaries took Bhedabheda-like positions, clarifying that Shankara’s nondual reading entered a field of competing Vedanta interpretations.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='8f24c364-a473-4359-a500-77dbf397cd9e'::uuid;
