INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('d488392f-4df0-4f67-8664-d2c1a901452c'::uuid,'APPROVE','{"claim_id":"d488392f-4df0-4f67-8664-d2c1a901452c","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"Later Vedanta is often mapped through Advaita, Vishishtadvaita and Dvaita; Ramanuja and Madhva developed influential readings that reject Shankara’s identity claim in different ways.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["c833b2a2-932f-4715-8339-d3f1860dc99d"],"original_passage_ids":["c7bb517f-d656-4831-9915-ba247f318b48"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Later Vedanta is often mapped through Advaita, Vishishtadvaita and Dvaita; Ramanuja and Madhva developed influential readings that reject Shankara’s identity claim in different ways.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"c833b2a2-932f-4715-8339-d3f1860dc99d","url":"https://iep.utm.edu/upanisad/","locator":"The Upanishads and Vedanta, lines 138–145","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"IEP distinguishes the three Vedanta branches and details Ramanuja''s and Madhva''s different objections to identity.","original_source_inspected":true,"material_limitation":"Interpretive claims are attributed to the scholarly entry; primary commentary or an independent specialist study may refine details.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
