INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('4ec3c901-037a-45cd-8925-41b457c04f70'::uuid,'APPROVE','{"claim_id":"4ec3c901-037a-45cd-8925-41b457c04f70","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"The widely repeated claim that Shankara was born at Kaladi in present-day Kerala is reported in later Shankaravijaya biographies; it is traditional biography, not independently documented early history.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["da61510f-9779-46c0-b5af-2f4aaefb9b94"],"original_passage_ids":["14fe189d-111b-49da-b08c-9dbbd6062717"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The widely repeated claim that Shankara was born at Kaladi in present-day Kerala is reported in later Shankaravijaya biographies; it is traditional biography, not independently documented early history.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":"da61510f-9779-46c0-b5af-2f4aaefb9b94","url":"https://plato.stanford.edu/entries/shankara/","locator":"Life and Works, lines 45–46","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"SEP places the Kaladi birth story in centuries-later hagiographies and says dependable biographical records are lacking.","original_source_inspected":true,"material_limitation":null,"removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
