INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('6ef8c100-50f7-4803-bf01-8ead5d774262'::uuid,'REVISE AND APPROVE','{"claim_id":"6ef8c100-50f7-4803-bf01-8ead5d774262","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"The Shankaravijayas, the major “conquests of Shankara” biographies, were composed centuries after his death; stories they tell—birth at Kaladi, travels, debates and miracles—belong first to hagiography.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["da61510f-9779-46c0-b5af-2f4aaefb9b94"],"original_passage_ids":["25a7116a-37f2-414c-a9a2-68a7289da5f6"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The Shankaravijaya biographies were composed centuries after Shankara''s death; their accounts of his birthplace, travels, and debates are hagiographical traditions.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"da61510f-9779-46c0-b5af-2f4aaefb9b94","url":"https://plato.stanford.edu/entries/shankara/","locator":"Life and Works, lines 45–47 and 57","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"SEP supports the late composition and listed biographical narratives. The original reference to miracles lacked a pinpoint in this entry and was removed.","original_source_inspected":true,"material_limitation":"Interpretive claims are attributed to the scholarly entry; primary commentary or an independent specialist study may refine details.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
