INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('7ea0f689-a9c1-4b95-8098-74ae820c7699'::uuid,'APPROVE','{"claim_id":"7ea0f689-a9c1-4b95-8098-74ae820c7699","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"There are no dependable historical records of Shankara’s life beyond clues in his writings, so modern accounts must separate reconstruction from later devotional narrative.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["da61510f-9779-46c0-b5af-2f4aaefb9b94"],"original_passage_ids":["5805b6c6-9bc9-4c69-98ab-e78c77dc9fe6"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"There are no dependable historical records of Shankara’s life beyond clues in his writings, so modern accounts must separate reconstruction from later devotional narrative.","epistemic_type":"METHODOLOGICAL","evidence_references":[{"source_id":"da61510f-9779-46c0-b5af-2f4aaefb9b94","url":"https://plato.stanford.edu/entries/shankara/","locator":"Life and Works, line 45","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"SEP directly states the absence of dependable life records apart from sparse clues in Shankara''s writings.","original_source_inspected":true,"material_limitation":null,"removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
