INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('3145b253-d7df-4c55-92c3-97d37e19b80e'::uuid,'APPROVE','{"claim_id":"3145b253-d7df-4c55-92c3-97d37e19b80e","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"In Shankara’s account, ritual and ethical action can purify the mind and prepare it for knowledge, but cannot themselves produce moksha as an action-result.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["a2a0752d-ffce-4a6f-b5a9-77186913ac3e"],"original_passage_ids":["c15b7f8b-b951-4802-b34b-f7f12482ccfe"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"In Shankara’s account, ritual and ethical action can purify the mind and prepare it for knowledge, but cannot themselves produce moksha as an action-result.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"a2a0752d-ffce-4a6f-b5a9-77186913ac3e","url":"https://iep.utm.edu/advaita-vedanta/","locator":"Error, True Knowledge and Practical Teachings, lines 74–75","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"IEP says knowledge alone liberates and action prepares or purifies the mind; this matches the two-part proposition.","original_source_inspected":true,"material_limitation":"Interpretive claims are attributed to the scholarly entry; primary commentary or an independent specialist study may refine details.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
