INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('17f2e466-30da-4300-8886-46f0fbd4de4c'::uuid,'APPROVE','{"claim_id":"17f2e466-30da-4300-8886-46f0fbd4de4c","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"For Advaita, consciousness is not merely a property possessed by Brahman; it is Brahman’s very nature.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["a2a0752d-ffce-4a6f-b5a9-77186913ac3e"],"original_passage_ids":["081cf0b6-4d57-4ef8-8087-93435d1f44c6"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"For Advaita, consciousness is not merely a property possessed by Brahman; it is Brahman’s very nature.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"a2a0752d-ffce-4a6f-b5a9-77186913ac3e","url":"https://iep.utm.edu/advaita-vedanta/","locator":"Brahman, Jiva, Isvara, and Maya, line 31","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"IEP explicitly says consciousness is Brahman''s nature rather than a property; this is a doctrinal account, not an empirical assertion.","original_source_inspected":true,"material_limitation":"Interpretive claims are attributed to the scholarly entry; primary commentary or an independent specialist study may refine details.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
