INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('42e1e4c3-c2d5-4588-9a61-4b09f5a0d498'::uuid,'APPROVE','{"claim_id":"42e1e4c3-c2d5-4588-9a61-4b09f5a0d498","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"Advaita is commonly rendered “non-duality,” but literally means “non-secondness”: Brahman is not one item alongside another independent reality.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["a2a0752d-ffce-4a6f-b5a9-77186913ac3e"],"original_passage_ids":["f96abbd8-4f4e-499b-8cf3-5505be200ed1"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Advaita is commonly rendered “non-duality,” but literally means “non-secondness”: Brahman is not one item alongside another independent reality.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"a2a0752d-ffce-4a6f-b5a9-77186913ac3e","url":"https://iep.utm.edu/advaita-vedanta/","locator":"Introduction, lines 3–4","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"IEP gives the literal non-secondness rendering and denies the world''s independent existence apart from Brahman.","original_source_inspected":true,"material_limitation":"Interpretive claims are attributed to the scholarly entry; primary commentary or an independent specialist study may refine details.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
