INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('62814db2-74ec-42eb-97e3-f8377d65acad'::uuid,'APPROVE','{"claim_id":"62814db2-74ec-42eb-97e3-f8377d65acad","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"Shankara treats the Upanishads not only as authorities but as texts that model methods of interpretation, using literary criteria to establish a coherent teaching.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["c833b2a2-932f-4715-8339-d3f1860dc99d"],"original_passage_ids":["7868b646-5dd5-498f-905f-2d5f3b3c4f3c"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Shankara treats the Upanishads not only as authorities but as texts that model methods of interpretation, using literary criteria to establish a coherent teaching.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"c833b2a2-932f-4715-8339-d3f1860dc99d","url":"https://iep.utm.edu/upanisad/","locator":"The Upanishads and Vedanta, lines 142–143","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"IEP explicitly says Shankara treated the Upanishads as models for interpretive method, using literary criteria.","original_source_inspected":true,"material_limitation":"Interpretive claims are attributed to the scholarly entry; primary commentary or an independent specialist study may refine details.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
