INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('5609a45d-ff75-4996-bc9f-556be05c0dba'::uuid,'REVISE AND APPROVE','{"claim_id":"5609a45d-ff75-4996-bc9f-556be05c0dba","personality_id":"a2cfad28-3f09-47e1-932c-149740c3e5cd","personality":"Rajaraja Chola I","original_claim_text":"Brihadisvara remains a major surviving material record of high Chola art and architecture and anchors Rajaraja’s long cultural legacy.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["ae8abe7a-5576-4e83-86f0-bfcd4ea240f6"],"original_passage_ids":["ebb4f6ef-ab5b-4672-ad8e-fc256aba7df0"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"UNESCO identifies the Brihadisvara Temple at Thanjavur, built under Rajaraja I, as a major example of Chola architecture and art.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"url":"https://whc.unesco.org/en/list/250/","locator":"Site description and Outstanding Universal Value, lines 4–5 and 50–61","source_id":null}],"verification_rationale":"UNESCO links the temple to Rajaraja I and evaluates the property as an outstanding Chola architectural example. The original claim about a ''long cultural legacy'' was too open-ended for this source and was narrowed.","original_source_inspected":false,"material_limitation":null,"removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
