INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('4a430925-c049-4438-a455-b4c2d2c2acaf'::uuid,'APPROVE','{"claim_id":"4a430925-c049-4438-a455-b4c2d2c2acaf","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"The Order''s biography says the Dakshineswar temple garden built by Rani Rasmani, centred on Kali as Bhavatarini, was dedicated on 31 May 1855, and that Ramakrishna came to it with his elder brother Ramkumar, who was appointed priest of the Kali temple.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["61914dc5-f03e-451c-81ef-145d18079b40"],"original_passage_ids":["74166853-47c7-49c7-bae9-792140f08f5a"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The Order''s biography says the Dakshineswar temple garden built by Rani Rasmani, centred on Kali as Bhavatarini, was dedicated on 31 May 1855, and that Ramakrishna came to it with his elder brother Ramkumar, who was appointed priest of the Kali temple.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/kali.htm","locator":"lines 3, 10–11","source_authority":"Swami Nikhilananda''s retrospective introduction to The Gospel of Sri Ramakrishna, hosted by the Ramakrishna Order; original chapter inspected 2026-10-19","independence_assessment":"Institutional devotional account; direct evidence for what the Order says, not independent corroboration of reported private or mystical events.","original_source_inspected":true}],"verification_rationale":"The Order text directly gives the dedication date, founder, shrine dedication, and Ramkumar appointment. The wording already attributes the account.","original_source_inspected":true,"material_limitation":"Retrospective institutional account; private and mystical events cannot be independently established from this source alone.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='The Order''s biography says the Dakshineswar temple garden built by Rani Rasmani, centred on Kali as Bhavatarini, was dedicated on 31 May 1855, and that Ramakrishna came to it with his elder brother Ramkumar, who was appointed priest of the Kali temple.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='4a430925-c049-4438-a455-b4c2d2c2acaf'::uuid;
