INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('ecc7fc2c-617c-4f29-b365-462f1c4aa0cb'::uuid,'APPROVE','{"claim_id":"ecc7fc2c-617c-4f29-b365-462f1c4aa0cb","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"The Ramakrishna Order''s biography says Gadadhar, later Ramakrishna, was born on 18 February 1836 at Kamarpukur, a village in Hooghly district, Bengal, to a devout brahmin family.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["61914dc5-f03e-451c-81ef-145d18079b40","d5a13923-a194-487e-8a9b-0d61f574d7e7"],"original_passage_ids":["d462c17d-eba3-4685-91ba-8cea0a1cddea"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The Ramakrishna Order''s biography says Gadadhar, later Ramakrishna, was born on 18 February 1836 at Kamarpukur, a village in Hooghly district, Bengal, to a devout brahmin family.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/boyhood.htm","locator":"lines 5, 7, 13","source_authority":"Swami Nikhilananda''s retrospective introduction to The Gospel of Sri Ramakrishna, hosted by the Ramakrishna Order; original chapter inspected 2026-10-19","independence_assessment":"Institutional devotional account; direct evidence for what the Order says, not independent corroboration of reported private or mystical events.","original_source_inspected":true}],"verification_rationale":"The Order text directly supplies place, date, childhood name, and brahmin family context. This is its traditional biographical dating.","original_source_inspected":true,"material_limitation":"Retrospective institutional account; private and mystical events cannot be independently established from this source alone.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
