INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('71062ea0-f9bd-4671-9b10-a7e4027d10c6'::uuid,'APPROVE','{"claim_id":"71062ea0-f9bd-4671-9b10-a7e4027d10c6","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"In Ramakrishna''s later account as the Order records it, longing for a vision of the Mother grew so unbearable that he seized the temple sword to end his life, and at that moment \"the blessed Mother revealed Herself\"; this is a reported mystical experience, not independently attested.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["61914dc5-f03e-451c-81ef-145d18079b40","8cd5175c-1fa9-4fc0-9d96-2edce7212fec"],"original_passage_ids":["ad090a89-415f-4aea-b4da-44d966b15d4e"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"In Ramakrishna''s later account as the Order records it, longing for a vision of the Mother grew so unbearable that he seized the temple sword to end his life, and at that moment \"the blessed Mother revealed Herself\"; this is a reported mystical experience, not independently attested.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/the_first_vision.htm","locator":"lines 13–15","source_authority":"Swami Nikhilananda''s retrospective introduction to The Gospel of Sri Ramakrishna, hosted by the Ramakrishna Order; original chapter inspected 2026-10-19","independence_assessment":"Institutional devotional account; direct evidence for what the Order says, not independent corroboration of reported private or mystical events.","original_source_inspected":true}],"verification_rationale":"Nikhilananda explicitly presents Ramakrishna''s later first-person recollection, including the sword and reported vision. The wording marks it as reported and not independently attested.","original_source_inspected":true,"material_limitation":"Retrospective institutional account; private and mystical events cannot be independently established from this source alone.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
