INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('9a849445-4c16-4ef2-bf13-c514db5f9a9c'::uuid,'APPROVE','{"claim_id":"9a849445-4c16-4ef2-bf13-c514db5f9a9c","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"Ramakrishna is quoted saying that after Totapuri left he remained for six months in a state of absolute identity with Brahman, unaware of day and night; this is a reported mystical state recorded by the Order and not independently verifiable.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["61914dc5-f03e-451c-81ef-145d18079b40"],"original_passage_ids":["7c49a682-9ea3-4775-9398-02b10ae84ecd"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Ramakrishna is quoted saying that after Totapuri left he remained for six months in a state of absolute identity with Brahman, unaware of day and night; this is a reported mystical state recorded by the Order and not independently verifiable.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/totapuris_lesson.htm","locator":"paragraph beginning ''After the departure of Totapuri''","source_authority":"Swami Nikhilananda''s retrospective introduction to The Gospel of Sri Ramakrishna, hosted by the Ramakrishna Order; original chapter inspected 2026-10-19","independence_assessment":"Institutional devotional account; direct evidence for what the Order says, not independent corroboration of reported private or mystical events.","original_source_inspected":true}],"verification_rationale":"The chapter quotes Ramakrishna''s reported six-month recollection. The wording correctly identifies an unverified subjective state.","original_source_inspected":true,"material_limitation":"Retrospective institutional account; private and mystical events cannot be independently established from this source alone.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
