INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('db679fec-a8ef-41cd-a1d9-a1138b0d2d01'::uuid,'APPROVE','{"claim_id":"db679fec-a8ef-41cd-a1d9-a1138b0d2d01","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"The Order says the Brahmani proclaimed him an Incarnation of God, and that the Vaishnava leader Vaishnavcharan, at a scholars'' conference convened by Mathur Babu, agreed that his experience of mahabhava signalled a rare manifestation of God in a man; Ramakrishna is reported to have felt relief that \"it is not a disease\".","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["61914dc5-f03e-451c-81ef-145d18079b40"],"original_passage_ids":["c53c98a1-b4bd-466c-a136-5ad23c6ed70a"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The Order says the Brahmani proclaimed him an Incarnation of God, and that the Vaishnava leader Vaishnavcharan, at a scholars'' conference convened by Mathur Babu, agreed that his experience of mahabhava signalled a rare manifestation of God in a man; Ramakrishna is reported to have felt relief that \"it is not a disease\".","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/the_brahmani.htm","locator":"lines 7–13","source_authority":"Swami Nikhilananda''s retrospective introduction to The Gospel of Sri Ramakrishna, hosted by the Ramakrishna Order; original chapter inspected 2026-10-19","independence_assessment":"Institutional devotional account; direct evidence for what the Order says, not independent corroboration of reported private or mystical events.","original_source_inspected":true}],"verification_rationale":"The text directly reports the Brahmani''s avatar proclamation, Vaishnavcharan''s agreement, and Ramakrishna''s reported response; all are attributed.","original_source_inspected":true,"material_limitation":"Retrospective institutional account; private and mystical events cannot be independently established from this source alone.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='The Order says the Brahmani proclaimed him an Incarnation of God, and that the Vaishnava leader Vaishnavcharan, at a scholars'' conference convened by Mathur Babu, agreed that his experience of mahabhava signalled a rare manifestation of God in a man; Ramakrishna is reported to have felt relief that "it is not a disease".',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='db679fec-a8ef-41cd-a1d9-a1138b0d2d01'::uuid;
