INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('e76a77c7-134b-4723-92c7-2af6224bd1b1'::uuid,'APPROVE','{"claim_id":"e76a77c7-134b-4723-92c7-2af6224bd1b1","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"The Order says that a few months after Sarada joined him at Dakshineswar in 1872 he arranged a special worship of the Divine Mother and seated Sarada herself as the living image; both reportedly went into samadhi, and the Order presents their bond as a spiritual companionship.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["2aa55178-75fe-4a1c-92b5-3ec77c532dca","61914dc5-f03e-451c-81ef-145d18079b40"],"original_passage_ids":["ecd02658-a920-444d-9fde-5b9dd1e9aaad"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The Order says that a few months after Sarada joined him at Dakshineswar in 1872 he arranged a special worship of the Divine Mother and seated Sarada herself as the living image; both reportedly went into samadhi, and the Order presents their bond as a spiritual companionship.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/relation_with_wife.htm","locator":"lines 3, 8–11","source_authority":"Swami Nikhilananda''s retrospective introduction to The Gospel of Sri Ramakrishna, hosted by the Ramakrishna Order; original chapter inspected 2026-10-19","independence_assessment":"Institutional devotional account; direct evidence for what the Order says, not independent corroboration of reported private or mystical events.","original_source_inspected":true}],"verification_rationale":"The chapter reports Sarada''s 1872 arrival, the worship ceremony, the reported samadhi, and the Order''s spiritual interpretation. The wording preserves attribution.","original_source_inspected":true,"material_limitation":"Retrospective institutional account; private and mystical events cannot be independently established from this source alone.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
