INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('01474b6e-2c2f-4a8f-b529-99002a07eede'::uuid,'REVISE AND APPROVE','{"claim_id":"01474b6e-2c2f-4a8f-b529-99002a07eede","personality_id":"9a66a004-b1ce-429d-946e-715ae059f730","personality":"Verghese Kurien","original_claim_text":"After the Anand cooperative demonstrated its model, Prime Minister Lal Bahadur Shastri backed a national board in 1965 to replicate it; the government’s sponsorship was central to scaling.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["162fa362-1a24-42ce-92fe-64a13cc81160"],"original_passage_ids":["b2faf07f-1369-4d40-8399-72432dcfe667"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"After the Kaira cooperative''s success, Prime Minister Lal Bahadur Shastri created the National Dairy Development Board in 1965 to replicate the model nationally.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":null,"url":"https://www.worldfoodprize.org/index.cfm/87428/40143/the_world_food_prize_pays_tribute_to_1989_laureate_dr_verghese_kurien","locator":"Achievements, lines 50–51","source_authority":"World Food Prize Foundation''s 2012 laureate tribute","independence_assessment":"Distinct original speech or institutional issuer account; additional institutional corroboration is named in the rationale where used.","original_source_inspected":true}],"verification_rationale":"The tribute directly supports the sequence, prime minister, board, and year. The broad causal claim about government sponsorship was removed.","original_source_inspected":true,"material_limitation":null,"removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
