INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('c49dd80e-e4b1-4a56-a005-bf7df968648d'::uuid,'APPROVE','{"claim_id":"c49dd80e-e4b1-4a56-a005-bf7df968648d","personality_id":"9a66a004-b1ce-429d-946e-715ae059f730","personality":"Verghese Kurien","original_claim_text":"Kurien helped establish the Institute of Rural Management Anand in 1979 to train managers for rural producer organizations, extending the model beyond dairy hardware.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["162fa362-1a24-42ce-92fe-64a13cc81160"],"original_passage_ids":["749ce9b1-8cfd-4a78-bb9c-6e059b9c4f75"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Kurien helped establish the Institute of Rural Management Anand in 1979 to train managers for rural producer organizations, extending the model beyond dairy hardware.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":null,"url":"https://www.nddb.coop/about/chairman/vkurien","locator":"Kurien biography, line 243","source_authority":"National Dairy Development Board institutional biography","independence_assessment":"Distinct original speech or institutional issuer account; additional institutional corroboration is named in the rationale where used.","original_source_inspected":true}],"verification_rationale":"NDDB directly records Kurien establishing IRMA in Anand in 1979 for cooperative management training and research; WFP tribute line 63 agrees.","original_source_inspected":true,"material_limitation":null,"removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
